'overall_bands' => [
 'very_low' => 'برآیند کلی پنج‌عاملی شما در این ارزیابی، پروفایل یکنواخت و کم‌نوسانی را نشان می‌دهد — یعنی هیچ‌کدام از پنج بُعد به‌شکل تند و متمایز برجسته نشده است. دو خوانش حرفه‌ای ممکن است: (۱) تعادل واقعی ویژگی‌ها (که در خود یک الگوی پایدار و انعطاف‌پذیر است)؛ (۲) سبک پاسخ‌دهی «میانه» به آیتم‌ها (central tendency) که در خودگزارشی رایج است. در هر دو حالت، داستان واقعی در «ریزشکل» تک‌تک ابعاد است: اختلاف‌های نسبی (مثلاً C بالاتر از E) برای انتخاب‌های روزمره‌تان معنادارتر از میانگین کلی است. توصیهٔ عملی: دو بُعد بالاتر و یک بُعد پایین‌تر نسبی‌تان را پیدا کنید و برنامهٔ رشد را روی همان قاعده بچینید، نه بر نمرهٔ تجمیعی.',
 'low' => 'برآیند کلی پروفایل شما در محدودهٔ ملایم‌تر از میانگین شدت قرار دارد؛ یعنی ابعاد پنج‌گانه به‌آرامی و بدون تندی افراطی عمل می‌کنند. این الگو معمولاً انعطاف رفتاری بالایی می‌سازد: می‌توانید خود را با نقش‌ها و محیط‌های متنوع وفق دهید، چون هیچ بُعدی فرمانِ مطلق شما نیست. ریسک بالقوهٔ این پروفایل، «کم‌امضا ماندن» در بحران‌های هویتی است؛ آن را با ثبت آگاهانهٔ سه ارزش شخصی و دو ترجیح کاری روشن جبران کنید — انعطاف فقط وقتی ثروت است که لنگر مشخص داشته باشد.',
 'medium' => 'برآیند کلی پروفایل شما در محدودهٔ میانه است؛ ترکیبی از قوت‌های مشخص و فضاهای خنثی. خوانش حرفه‌ایِ نمرهٔ کلی در FFM به‌تنهایی کافی نیست — داستان اصلی در «شکل پروفایل» است: کدام دو بُعد از بقیه بالاترند و کدام یک پایین‌تر؟ همان مثلث، الگوی انتخاب شریک‌زندگی، شغل و سبک ارتباط شماست. به عنوان مثال E بالا + O بالا = رهبرِ الهام‌بخشِ ماجراجو؛ C بالا + A بالا = یارِ دقیقِ قابل‌اعتماد. از تفکیک‌نامهٔ ابعاد در فصل‌های همین گزارش استفاده کنید و سپس در فصلِ پایانی «پیوند کاربردی»، نقشهٔ ۶ هفته‌ای‌تان را بردارید.',
 'high' => 'برآیند کلی پروفایل شما چهره‌های برجسته و متمایزی دارد؛ یعنی یک یا دو بُعد به‌شکل معناداری قوی‌تر از بقیه عمل می‌کنند و امضای شخصیتیِ روشنی ساخته‌اند. این وضوح یک سرمایه است: وقتی بدانید «چه کسی هستید»، انتخاب محیط سازگار (person-environment fit) بسیار دقیق‌تر می‌شود — پژوهش‌های Holland و Kristof-Brown نشان می‌دهند تناسب شخصیت-محیط، پیش‌بینی‌کنندهٔ اصلی رضایت و عملکرد است. مراقبت متقابل: هر بُعد غالب، سایهٔ همراه دارد (C بالا ← سخت‌گیری؛ O بالا ← بی‌ثباتی در روال؛ E بالا ← نیاز به محرک مداوم). فصلِ تفکیک ابعاد، هر سایه را نام برده و تعادل‌بخش داده است — آن‌ها را جدی بگیرید.',
 'very_high' => 'برآیند کلی پروفایل شما بسیار مشخص و «واضح» است؛ ابعاد غالب به‌خوبی تعریف‌شده‌اند و الگوی شخصیتی‌تان قابل‌تشخیص است. در پژوهش‌های FFM، پروفایل واضح هم امتیاز است هم مسئولیت: امتیاز، چون انتخاب‌های سازگار با خود (نقش، شریک، محیط) را ساده می‌کند؛ مسئولیت، چون هر تندی، در محیط ناسازگار هزینهٔ واقعی می‌سازد. دو کاربرد عینی: (۱) برای تصمیم‌های بزرگ سال (شغل، مهاجرت، رابطهٔ جدی)، فهرست «سازگاری با پروفایل» را کنار بقیهٔ معیارها بگذارید — نادیده‌گرفتن آن در بلندمدت، هزینه‌بر است؛ (۲) برای هر بُعد غالب، یک «مکمل انسانی» یا «مکمل ساختاری» تعریف کنید (مثلاً اگر O خیلی بالاست، همکارِ C بالا یا ابزار تقویمی سفت‌وسخت، تعادل را می‌سازد). شخصیت نه سرنوشت است، نه بازیچه — نقشه‌ای است برای انتخاب آگاهانه.',
